use serde::Serialize;use std::path::Path;use walkdir::WalkDir;
#[derive(Serialize)]struct Track{id:String,title:String,artist:String,path:String,url:String}
fn supported(p:&Path)->bool{p.extension().and_then(|x|x.to_str()).map(|x|matches!(x.to_ascii_lowercase().as_str(),"mp3"|"flac"|"wav"|"m4a"|"aac"|"ogg")).unwrap_or(false)}
#[tauri::command]fn scan_music(folder:String)->Result<Vec<Track>,String>{let root=Path::new(&folder);if !root.is_dir(){return Err("Selected path is not a folder".into())}let mut tracks=Vec::new();for e in WalkDir::new(root).follow_links(false).into_iter().filter_map(Result::ok){let p=e.path();if !e.file_type().is_file()||!supported(p){continue}let title=p.file_stem().and_then(|x|x.to_str()).unwrap_or("Unknown").to_string();let path=p.to_string_lossy().to_string();let url=format!("asset://localhost/{}",urlencoding::encode(&path.replace('\\',"/")));tracks.push(Track{id:path.clone(),title,artist:"Local file".into(),path,url});}tracks.sort_by(|a,b|a.title.to_lowercase().cmp(&b.title.to_lowercase()));Ok(tracks)}
#[cfg_attr(mobile,tauri::mobile_entry_point)]pub fn run(){tauri::Builder::default().plugin(tauri_plugin_dialog::init()).plugin(tauri_plugin_opener::init()).invoke_handler(tauri::generate_handler![scan_music]).run(tauri::generate_context!()).expect("error while running application");}